# Simple central difference derivative
def derivative(func, x0, dx=1e-6, args=()):
    return (func(x0 + dx, *args) - func(x0 - dx, *args)) / (2.0 * dx)

def f(x, a):
    return a * x**2

print(derivative(f, 2.0, args=(3.0,)))
# Expected: 2*a*x = 2*3*2 = 12
